import{_ as a,a as e}from"./chunks/dochazka_typ.DsSXJvoi.js";import{_ as n,o as t,c as s,aa as i}from"./chunks/framework.BAs_AphD.js";const c=JSON.parse('{"title":"Novinky: docházkové systémy v nastavení domény","description":"","frontmatter":{"title":"Novinky: docházkové systémy v nastavení domény"},"headers":[],"relativePath":"news/dochazkove-systemy.md","filePath":"news/dochazkove-systemy.md","lastUpdated":1795418046000}'),d={name:"news/dochazkove-systemy.md"};function r(p,o,l,h,v,y){return t(),s("div",null,[...o[0]||(o[0]=[i('<h1 id="dochazkove-systemy-si-nove-napojite-sami" tabindex="-1">Docházkové systémy si nově napojíte sami <a class="header-anchor" href="#dochazkove-systemy-si-nove-napojite-sami" aria-label="Permalink to &quot;Docházkové systémy si nově napojíte sami&quot;">​</a></h1><p>Napojení stavebního deníku na docházkový systém už nemusíte domlouvat s naší podporou. Nově si ho nastavíte sami v detailu domény, a to i pro víc docházkových systémů najednou.</p><p><strong>Co je nového</strong></p><ul><li><a href="#nova-zalozka-nastaveni-dochazky">Nová záložka Nastavení docházky</a></li><li><a href="#vic-dochazkovych-systemu-na-jedne-domene">Víc docházkových systémů na jedné doméně</a></li><li><a href="#nove-podporujeme-fingera">Nově podporujeme Fingera</a></li><li><a href="#kontrola-napojeni-pri-ulozeni">Kontrola napojení při uložení</a></li><li><a href="#nactene-osoby-poznate-podle-ikony">Načtené osoby poznáte podle ikony</a></li></ul><h2 id="nova-zalozka-nastaveni-dochazky" tabindex="-1">Nová záložka Nastavení docházky <a class="header-anchor" href="#nova-zalozka-nastaveni-dochazky" aria-label="Permalink to &quot;Nová záložka Nastavení docházky&quot;">​</a></h2><p>V detailu domény přibyla záložka <strong>Nastavení docházky</strong>. Administrátor domény na ní tlačítkem <strong>Nový docházkový systém</strong> přidá napojení: vybere typ docházky, napojení pojmenuje a vyplní přístupové údaje od dodavatele docházkového systému. V deníku pak v Nastavení deníku jen vybere, ze kterého systému a terminálu se má docházka načítat.</p><figure class="shot" style="--w:652px;"><img src="'+a+'" alt="Záložka Nastavení docházky v detailu domény s tlačítkem Nový docházkový systém" loading="lazy"></figure><h2 id="vic-dochazkovych-systemu-na-jedne-domene" tabindex="-1">Víc docházkových systémů na jedné doméně <a class="header-anchor" href="#vic-dochazkovych-systemu-na-jedne-domene" aria-label="Permalink to &quot;Víc docházkových systémů na jedné doméně&quot;">​</a></h2><p>Používá každá stavba jiný docházkový systém? Přidejte do domény víc napojení a u každého deníku vyberte to správné. Stavbu kvůli jinému systému už není nutné přesouvat do jiné domény. Napojení pojmenujte tak, aby se dala snadno rozlišit, například „Sysdo – Ostrava“ a „Convision – Brno“.</p><h2 id="nove-podporujeme-fingera" tabindex="-1">Nově podporujeme Fingera <a class="header-anchor" href="#nove-podporujeme-fingera" aria-label="Permalink to &quot;Nově podporujeme Fingera&quot;">​</a></h2><p>Docházku načtete ze systémů <strong>Convision</strong>, <strong>Sysdo</strong> (i v seskupené podobě), <strong>WinPak</strong>, <strong>AdamAssistant</strong> a nově také <strong>Fingera</strong>.</p><figure class="shot" style="--w:376px;"><img src="'+e+'" alt="Seznam Typ docházky: Convision, Sysdo, WinPak, Sysdo seskupené, AdamAssistant, Fingera" loading="lazy"></figure><h2 id="kontrola-napojeni-pri-ulozeni" tabindex="-1">Kontrola napojení při uložení <a class="header-anchor" href="#kontrola-napojeni-pri-ulozeni" aria-label="Permalink to &quot;Kontrola napojení při uložení&quot;">​</a></h2><p>Buildary při uložení napojení rovnou vyzkouší, jestli se do docházkového systému dovolá. Chybné heslo nebo API klíč tak zjistíte hned, ne až při prvním importu docházky do deníku.</p><h2 id="nactene-osoby-poznate-podle-ikony" tabindex="-1">Načtené osoby poznáte podle ikony <a class="header-anchor" href="#nactene-osoby-poznate-podle-ikony" aria-label="Permalink to &quot;Načtené osoby poznáte podle ikony&quot;">​</a></h2><p>Záznamy v sekci <strong>Osoby na staveništi</strong>, které přišly z docházkového systému, jsou označené ikonou. Na první pohled je tak odlišíte od osob zapsaných ručně.</p><hr><p>Podrobný postup najdete na stránce <a href="/buildary-help-preview/diary/attendance_system">Docházkový systém</a>.</p>',18)])])}const u=n(d,[["render",r]]);export{c as __pageData,u as default};
